<?php $pageTitle=page_title('Pre-orders'); $page='farmer-orders'; ?>
<div class="dashboard-head reveal"><div><span class="eyebrow">Order management</span><h1>Pre-orders</h1><p>Accept, decline, prepare, and complete customer pickup orders.</p></div><a class="btn btn-light" href="<?= e(url('farmer-slots')) ?>"><?= icon('calendar') ?> View slots</a></div>
<div class="tabs"><a class="tab-link <?= $status===''?'active':'' ?>" href="<?= e(url('farmer-orders')) ?>">All</a><?php foreach(['placed'=>'Needs response','accepted'=>'Accepted','ready'=>'Ready','completed'=>'Completed','declined'=>'Declined'] as $key=>$label): ?><a class="tab-link <?= $status===$key?'active':'' ?>" href="<?= e(url('farmer-orders',['status'=>$key])) ?>"><?= e($label) ?></a><?php endforeach; ?></div>
<div class="content-card card"><?php if($orders): ?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Pickup</th><th>Items</th><th>Value</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td><strong><?= e($order['order_number']) ?></strong><br><small class="text-muted"><?= format_date($order['created_at'],'M j · g:i A') ?></small></td><td><?= e($order['customer_name']) ?><br><small class="text-muted"><?= e($order['customer_phone']) ?></small></td><td><?= format_date($order['pickup_date'] ?? $order['created_at'],'M j, Y') ?><br><small class="text-muted"><?= e($order['market_name']) ?></small></td><td><?= (int)$order['item_count'] ?></td><td><strong><?= money($order['subtotal_cents']/100) ?></strong></td><td><?= status_pill($order['status']) ?></td><td><a class="btn btn-light btn-sm" href="<?= e(url('farmer-order',['id'=>$order['id']])) ?>">Manage</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><span class="empty-state-icon">📦</span><h3>No orders in this view</h3><p>New customer pre-orders will appear here.</p></div><?php endif; ?></div>
